state = {'phase': 'unpin', 'init_progress': None}

def control(obs):
    screen_gaze = obs.get('rig', {}).get('screen_gaze_deg', -23.0) or -23.0
    hitch = obs.get('hitch_deg', 0.0)
    progress = obs.get('progress', {}).get('covered', 0.0)
    cam_walls = obs.get('views', {}).get('camera', {}).get('walls', [])

    if state['init_progress'] is None:
        state['init_progress'] = progress

    if state['phase'] == 'unpin':
        if progress > state['init_progress'] - 1.5:
            return {'steer_deg': -12.0, 'speed_mps': 1.0, 'look_deg': screen_gaze}
        else:
            state['phase'] = 'reverse'

    target_hitch = -16.0
    target = obs.get('target', {})
    if target.get('in_sight', False):
        bearing = target.get('bearing_deg', 0.0)
        dev = bearing - 180.0 if bearing > 0 else bearing + 180.0
        target_hitch = -max(min(dev * 0.8, 26.0), -26.0)
    elif cam_walls:
        far_points = [p for p in cam_walls if p[1] > 3.0]
        if not far_points:
            target_hitch = 0.0

    left_dists = [p[1] for p in cam_walls if (p[0] > 0 or p[0] < -170)]
    right_dists = [p[1] for p in cam_walls if (-170 <= p[0] <= 0)]
    if left_dists and min(left_dists) < 0.9:
        target_hitch -= 5.0
    if right_dists and min(right_dists) < 0.8:
        target_hitch += 5.0

    target_hitch = max(min(target_hitch, 24.0), -24.0)
    error = hitch - target_hitch
    steer = error * 2.3
    steer = max(min(steer, 34.0), -34.0)
    speed = -0.65 if abs(hitch) < 20.0 else -0.4
    return {'steer_deg': steer, 'speed_mps': speed, 'look_deg': screen_gaze}

