import math

phase = 'pull_fwd'
fwd_start_prog = None

def control(obs):
    global phase, fwd_start_prog
    prog = obs.get('progress', {}).get('covered', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    views = obs.get('views', {})

    if phase == 'pull_fwd':
        if fwd_start_prog is None:
            fwd_start_prog = prog
        if (fwd_start_prog - prog) >= 2.0 or obs.get('counters', {}).get('gear_changes', 0) >= 3:
            phase = 'reverse'
        else:
            return {'steer_deg': 20.0, 'speed_mps': 1.0, 'look_deg': 0.0}

