import math

# Rail touches: 8 (max 8) -> critical limit! No more touches allowed.
# Trailer rear-right touched at progress 10.0m with hitch = +12.9 deg.
# We need to pull forward ~2.5m with modest left steer (+15 deg) so the tractor
# moves laterally to the left and lines up with the curve corridor,
# then reverse cleanly following the corridor.

phase = 'pull_fwd'
fwd_dist = 0.0

def control(obs):
    global phase, fwd_dist
    dt = obs.get('dt', 0.1)
    v = obs.get('motion', {}).get('v_mps', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    views = obs.get('views', {})

    if phase == 'pull_fwd':
        if v > 0.05:
            fwd_dist += v * dt
        if fwd_dist >= 2.5:
            phase = 'reverse'
        else:
            return {'steer_deg': 15.0, 'speed_mps': 0.65, 'look_deg': 170.0}

    # Reversing phase:
    right_rails_y = []
    for vname in ['direct', 'periphery', 'left_mirror', 'right_mirror']:
        vi = views.get(vname)
        if not vi:
            continue
        ox, oy = vi['origin']
        for b_deg, d in vi.get('walls', []):
            b_rad = math.radians(b_deg)
            px = ox + d * math.cos(b_rad)
            py = oy + d * math.sin(b_rad)
            if -7.5 <= px <= -1.5 and py < 1.0:
                right_rails_y.append(py)

    target_hitch = 14.0
    if right_rails_y:
        closest_right = max(right_rails_y)
        t_rear_y = obs.get('rig', {}).get('trailer_rear', [-6.0, 1.0])[1]
        clearance = (t_rear_y - 1.2) - closest_right
        if clearance < 0.5:
            target_hitch = 18.0
        elif clearance > 0.9:
            target_hitch = 10.0

    hitch_err = hitch - target_hitch
    cmd_steer = max(-25.0, min(25.0, hitch_err * 2.2))
    return {'steer_deg': cmd_steer, 'speed_mps': -0.4, 'look_deg': 170.0}

