import math

state = {
    'mode': 'wait_penalty',
    'fwd_steps': 0,
    'fwd_done': False,
}

def control(obs):
    look_deg = 160.0
    hitch = obs.get('hitch_deg', 0.0)
    steer = obs.get('steer_deg', 0.0)
    hold = obs.get('motion', {}).get('hold_s', 0.0)
    status = obs.get('status', '')

    if hold > 0.05 or status == 'PINNED':
        return {'steer_deg': 25.0, 'speed_mps': 0.0, 'look_deg': look_deg}

    if not state['fwd_done']:
        state['fwd_steps'] += 1
        if state['fwd_steps'] < 18:
            return {'steer_deg': 20.0, 'speed_mps': 0.45, 'look_deg': look_deg}
        elif abs(hitch) > 6.0 and state['fwd_steps'] < 30:
            return {'steer_deg': 10.0, 'speed_mps': 0.4, 'look_deg': look_deg}
        else:
            state['fwd_done'] = True

    speed = -0.38
    views = obs.get('views', {})
    left_walls = []
    right_walls = []

    for vname, v in views.items():
        ox, oy = v.get('origin', [0.0, 0.0])
        for b_deg, d in v.get('walls', []):
            rad = math.radians(b_deg)
            px = ox + d * math.cos(rad)
            py = oy + d * math.sin(rad)
            if -4.0 < px < 1.0:
                if py > 0.15:
                    left_walls.append(py)
                elif py < -0.15:
                    right_walls.append(-py)

    lane_bias = 0.0
    if left_walls and right_walls:
        min_l = min(left_walls)
        min_r = min(right_walls)
        lane_bias = min_l - min_r
    elif left_walls:
        min_l = min(left_walls)
        lane_bias = 1.3 - min_l
    elif right_walls:
        min_r = min(right_walls)
        lane_bias = min_r - 1.3

    target_hitch = max(-8.0, min(8.0, lane_bias * 8.0))
    hitch_err = hitch - target_hitch
    target_steer = hitch_err * 2.2 + hitch * 0.5
    target_steer = max(-30.0, min(30.0, target_steer))

    return {
        'steer_deg': target_steer,
        'speed_mps': speed,
        'look_deg': look_deg
    }

