import math

state = {
    'pinned_steps': 0,
    'recovered': False
}

def control(obs):
    look_deg = 160.0
    hitch = obs.get('hitch_deg', 0.0)
    status = obs.get('status', '')
    hold = obs.get('motion', {}).get('hold_s', 0.0)

    # Trailer rear-left touched the rail.
    # Clear contact by pulling forward slightly with steer to the right.
    if hold > 0.1:
        return {'steer_deg': -20.0, 'speed_mps': 0.0, 'look_deg': look_deg}

    if status == 'PINNED' or not state['recovered']:
        state['pinned_steps'] += 1
        if state['pinned_steps'] < 16:
            return {'steer_deg': -20.0, 'speed_mps': 0.4, 'look_deg': look_deg}
        elif state['pinned_steps'] < 24:
            return {'steer_deg': 5.0, 'speed_mps': 0.35, 'look_deg': look_deg}
        else:
            state['recovered'] = True

    speed = -0.32

    # Check wall distances
    views = obs.get('views', {})
    left_y = []
    right_y = []
    for vname, v in views.items():
        ox, oy = v.get('origin', [0.0, 0.0])
        for b_deg, d in v.get('walls', []):
            rad = math.radians(b_deg)
            px = ox + d * math.cos(rad)
            py = oy + d * math.sin(rad)
            if -4.5 < px < 1.0:
                if py > 0.1:
                    left_y.append(py)
                elif py < -0.1:
                    right_y.append(-py)

    offset = 0.0
    if left_y and right_y:
        min_l = min(left_y)
        min_r = min(right_y)
        offset = (min_r - min_l) / 2.0
    elif left_y:
        min_l = min(left_y)
        offset = max(0.0, 1.2 - min_l)
    elif right_y:
        min_r = min(right_y)
        offset = min(0.0, min_r - 1.2)

